// Ambient declarations for the text-import attribute Bun supports.
// The actual files (runtime.bundle.js / runtime.bundle.css + vendor
// copies) are generated by `scripts/build-runtime-bundle.ts` before
// `bun build`. The wildcards cover both the runtime bundle and any
// vendored .js / .css we embed.

declare module '*.bundle.js' {
  const content: string
  export default content
}

declare module '*.bundle.css' {
  const content: string
  export default content
}

declare module '*.min.js' {
  const content: string
  export default content
}

// A vendored file's licence or notice, imported as text (it travels with the
// file in a standalone page).
declare module '*.LICENSE' {
  const content: string
  export default content
}

declare module '*.NOTICE' {
  const content: string
  export default content
}
